<script>
(() => {
    const root=document.getElementById('admin-guides'), $=selector=>root.querySelector(selector), editor=$('#ga-editor'), form=$('#ga-form'), categoryDialog=$('#ga-category-dialog');
    const make=(tag,cls,text)=>{const node=document.createElement(tag);node.className=cls;if(text!==undefined)node.textContent=text;return node;};
    const safeUrl=value=>{if(typeof value!=='string'||!value.trim())return '';try{const url=new URL(value,location.origin);return url.origin===location.origin&&['http:','https:'].includes(url.protocol)?url.href:'';}catch{return '';}};
    const bodyEditor=(()=>{
        const visual=$('#ga-body-visual'),source=$('#ga-body'),toolbar=root.querySelector('.ga-toolbar');let selection=null,dirty=false;
        const inside=range=>range&&visual.contains(range.startContainer)&&visual.contains(range.endContainer);
        function remember(){const selected=getSelection();if(selected.rangeCount&&inside(selected.getRangeAt(0)))selection=selected.getRangeAt(0).cloneRange();}
        function restore(){visual.focus({preventScroll:true});const selected=getSelection(),range=inside(selection)?selection:document.createRange();if(!inside(selection)){range.selectNodeContents(visual);range.collapse(false);}selected.removeAllRanges();selected.addRange(range);}
        function sync(){if(dirty)source.value=visual.innerHTML;}
        function changed(){dirty=true;sync();remember();$('#ga-preview').hidden=true;}
        function states(){const selected=getSelection();if(!selected.rangeCount||!inside(selected.getRangeAt(0)))return;const node=selected.anchorNode.nodeType===Node.ELEMENT_NODE?selected.anchorNode:selected.anchorNode.parentElement;
            toolbar.querySelectorAll('[data-wrap]').forEach(button=>{const tag=button.dataset.wrap;let on=false;
                if(tag==='strong')on=document.queryCommandState('bold');else if(tag==='em')on=document.queryCommandState('italic');else if(tag==='ul')on=document.queryCommandState('insertUnorderedList');else if(tag==='ol')on=document.queryCommandState('insertOrderedList');else on=Boolean(node.closest(tag)&&visual.contains(node.closest(tag)));
                button.setAttribute('aria-pressed',String(on));});}
        // Native editing preserves selections and undo history without a third-party editor.
        function command(tag){remember();restore();document.execCommand('styleWithCSS',false,false);const commands={strong:'bold',em:'italic',ul:'insertUnorderedList',ol:'insertOrderedList'},name=commands[tag]||'formatBlock';
            if(!document.queryCommandSupported(name)){message('#ga-form-error','Trình duyệt chưa hỗ trợ thao tác định dạng này.');return;}
            document.execCommand(name,false,commands[tag]?null:tag);changed();states();}
        toolbar.querySelectorAll('[data-wrap]').forEach(button=>{button.addEventListener('mousedown',event=>event.preventDefault());button.addEventListener('click',()=>command(button.dataset.wrap));});
        visual.addEventListener('input',changed);visual.addEventListener('focus',()=>document.execCommand('defaultParagraphSeparator',false,'p'));
        visual.addEventListener('paste',event=>{event.preventDefault();restore();document.execCommand('insertText',false,event.clipboardData?.getData('text/plain')||'');changed();});
        visual.addEventListener('drop',event=>event.preventDefault());
        document.addEventListener('selectionchange',()=>{remember();states();});
        visual.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&['b','i'].includes(event.key.toLowerCase())){event.preventDefault();command(event.key.toLowerCase()==='b'?'strong':'em');}});
        return {sync,load(html){/* Admin detail API already sanitizes this HTML server-side. */visual.innerHTML=html;source.value=html;selection=null;dirty=false;toolbar.querySelectorAll('[data-wrap]').forEach(button=>button.setAttribute('aria-pressed','false'));},required(value){visual.setAttribute('aria-required',String(value));source.required=false;},disabled(value){visual.contentEditable=String(!value);visual.setAttribute('aria-disabled',String(value));}};
    })();
    let categories=[],rows=[],page=1,lastPage=1,currentId=null,categoryId=null,serial=0,coverUrl='',savedCover='',busy=false,actionPending=false,undoId=null,undoTitle='',savedPublicationValue='',savedPublicationInput='';
    async function api(endpoint,options={}){const response=await adminApi('/guides'+endpoint,options);const data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.errors?Object.values(data.errors).flat().join('\n'):data.message||'Chưa thể tải dữ liệu. Vui lòng thử lại.');error.code=data.code;throw error;}return data;}
    function message(id,text){$(id).textContent=text;$(id).hidden=!text;}
    function options(select,items,empty){const previous=select.value;select.replaceChildren(new Option(empty,''),...items.map(item=>new Option(item.name+(item.is_active===false?' · đang ẩn':''),item.id)));select.value=previous;}
    const categoryName=value=>value.normalize('NFC').trim().replace(/\s+/g,' ');
    const findCategory=name=>categories.find(item=>categoryName(item.name).toLocaleLowerCase('vi')===categoryName(name).toLocaleLowerCase('vi'));
    function categorySuggestions(){$('#ga-category-suggestions').replaceChildren(...categories.map(item=>new Option(item.name+(item.is_active===false?' · đang ẩn':''),item.name)));}
    async function meta(){const data=await api('/meta');categories=data.categories;categorySuggestions();options($('#ga-category-filter'),categories,'Tất cả danh mục');options($('#ga-location'),data.locations,'Không liên kết địa phương');$('#ga-create').disabled=false;$('#ga-categories').disabled=false;renderCategories();}
    async function resolveCategory(){const name=categoryName($('#ga-category').value);if(!name)return '';const existing=findCategory(name);if(existing)return existing.id;
        try{const created=await api('/categories',{method:'POST',body:JSON.stringify({name,is_active:true})});categories.push(created);categorySuggestions();return created.id;}
        catch(error){try{await meta();}catch{}const created=findCategory(name);if(created)return created.id;throw error;}}
    function state(name){['loading','error','unavailable','empty','table','pagination'].forEach(key=>$('#ga-'+key).hidden=key!==name);}
    function failed(error){if(error.code==='GUIDES_NOT_READY'){$('#ga-create').disabled=true;$('#ga-categories').disabled=true;state('unavailable');}else{$('#ga-error-message').textContent=error.message||'Chưa thể tải dữ liệu Cẩm nang.';state('error');}}
    function button(text,fn,action='edit'){const node=make('button','ga-button',text);node.type='button';node.dataset.adminAction=action;node.addEventListener('click',fn);return node;}
    function renderRows(){
        $('#ga-rows').replaceChildren();rows.forEach(item=>{const row=make('tr',''),postCell=make('td',''),post=make('div','ga-post'),image=safeUrl(item.cover_url);if(image){const img=make('img','ga-thumb');img.src=image;img.alt='';post.append(img);}else post.append(make('div','ga-thumb'));const label=make('div','');label.append(make('strong','',item.title),make('small','',item.legacy_id?'Blog gốc #'+item.legacy_id:item.author_name||'Chưa có tác giả'));post.append(label);postCell.append(post);const category=make('td','',item.category?.name||'Chưa phân loại'),status=make('td',''),badge=make('span','ga-badge'+(item.status==='published'?' ga-badge--published':''),item.archived_at?'Đã lưu trữ':item.status==='draft'?'Bản nháp / ẩn':new Date(item.published_at)>new Date()?'Hẹn ngày xuất bản':item.category?.is_active?'Đã xuất bản':'Danh mục đang ẩn');badge.dataset.adminTone=item.archived_at||item.status==='draft'?'neutral':new Date(item.published_at)>new Date()?'warning':item.category?.is_active?'success':'neutral';status.append(badge);const date=make('td','',new Date(item.updated_at).toLocaleDateString('vi-VN')),actions=make('td',''),group=make('div','ga-actions');
            if(item.archived_at)group.append(button('Khôi phục',()=>action(item.id,'restore'),'restore'));else{group.append(button('Chỉnh sửa',()=>open(item.id)),button('Lưu trữ',()=>action(item.id,'archive'),'archive'));if(item.status==='published'&&item.category?.is_active&&new Date(item.published_at)<=new Date()){const link=make('a','ga-button','Xem ↗');link.dataset.adminAction='view';link.href=safeUrl(item.public_url);group.append(link);}}
            actions.append(group);row.append(postCell,category,status,date,actions);$('#ga-rows').append(row);
        });
    }
    function syncArchiveView(){const archived=$('#ga-archive-filter').value==='1';for(const [id,on] of [['#ga-active-tab',!archived],['#ga-archived-tab',archived]]){$(id).setAttribute('aria-pressed',String(on));$(id).classList.toggle('ga-primary',on);}$('#ga-status-filter').disabled=archived;if(archived)$('#ga-status-filter').value='';$('#ga-empty').textContent=archived?'Chưa có bài đã lưu trữ phù hợp.':'Chưa có bài viết phù hợp. Thay đổi bộ lọc hoặc viết một bài mới.';}
    async function archiveView(value,drafts=false){$('#ga-archive-filter').value=value;$('#ga-status-filter').value=drafts?'draft':'';$('#ga-category-filter').value='';$('#ga-query').value='';page=1;await load();}
    async function load(){syncArchiveView();const request=++serial;state('loading');const params=new URLSearchParams({page,archived:$('#ga-archive-filter').value});if($('#ga-status-filter').value)params.set('status',$('#ga-status-filter').value);if($('#ga-category-filter').value)params.set('category_id',$('#ga-category-filter').value);if($('#ga-query').value.trim())params.set('q',$('#ga-query').value.trim());try{const data=await api('?'+params);if(request!==serial)return;rows=data.data;lastPage=data.meta.last_page;renderRows();state(rows.length?'table':'empty');$('#ga-pagination').hidden=lastPage<=1;$('#ga-prev').disabled=page<=1;$('#ga-next').disabled=page>=lastPage;$('#ga-page-label').textContent=page+' / '+lastPage;}catch(error){if(request===serial)failed(error);}}
    function showCover(){if(coverUrl){URL.revokeObjectURL(coverUrl);coverUrl='';}const file=$('#ga-cover-file').files[0];if(file){coverUrl=URL.createObjectURL(file);$('#ga-remove-cover').checked=false;}const url=coverUrl||($('#ga-remove-cover').checked?'':safeUrl(savedCover));$('#ga-cover-image').hidden=!url;$('#ga-no-cover').hidden=Boolean(url);if(url)$('#ga-cover-image').src=url;else $('#ga-cover-image').removeAttribute('src');}
    function dateInput(value){if(!value)return '';const date=new Date(value);if(Number.isNaN(date.valueOf()))return '';const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);return local.toISOString().slice(0,19);}
    function syncStatus(){const publishing=$('#ga-status').value==='published';$('#ga-submit').textContent=publishing?'Lưu và xuất bản':'Lưu bản nháp';$('#ga-submit').dataset.adminAction=publishing?'publish':'save';for(const selector of ['#ga-category','#ga-excerpt','#ga-author'])$(selector).required=publishing;bodyEditor.required(publishing);}
    async function open(id=null){message('#ga-feedback','');try{const item=id?await api('/'+id):{};currentId=id;form.reset();message('#ga-form-error','');$('#ga-preview').replaceChildren();$('#ga-preview').hidden=true;$('#ga-editor-title').textContent=id?'Chỉnh sửa bài viết':'Viết bài mới';$('#ga-title').value=item.title||'';$('#ga-excerpt').value=item.excerpt||'';bodyEditor.load(item.body_html||'');$('#ga-category').value=item.category?.name||'';$('#ga-location').value=item.location_id||'';$('#ga-author').value=item.author_name||'';$('#ga-slug').value=item.slug||'';$('#ga-status').value=item.status||'draft';$('#ga-published-at').value=dateInput(item.published_at);savedPublicationValue=item.published_at||'';savedPublicationInput=$('#ga-published-at').value;$('#ga-published-at').dispatchEvent(new Event('change'));$('#ga-featured').checked=Boolean(item.is_featured);savedCover=item.cover_url||'';showCover();$('#ga-legacy-note').hidden=!item.legacy_id;$('#ga-legacy-note').textContent=item.legacy_id?'Giữ liên kết Blog gốc #'+item.legacy_id+'. Trạng thái nội dung khi chuyển đổi: '+({complete:'đầy đủ',empty:'file rỗng',missing:'thiếu file',needs_review:'cần rà soát'}[item.legacy_import_state]||'chưa xác định')+'. Bản gốc và metadata được bảo toàn; tên tác giả chưa được suy đoán.':'';syncStatus();editor.showModal();}catch(error){message('#ga-feedback',error.message);}}
    async function action(id,type){if(actionPending)return;actionPending=true;$('#ga-undo').disabled=true;message('#ga-feedback','');const title=rows.find(item=>item.id===id)?.title||undoTitle;
        try{await api('/'+id+(type==='restore'?'/restore':''),{method:type==='restore'?'POST':'DELETE'});$('#ga-notice').hidden=false;
            if(type==='archive'){undoId=id;undoTitle=title;$('#ga-notice-text').textContent='Đã lưu trữ “'+title+'”. Nội dung và ảnh được giữ nguyên trong mục Đã lưu trữ.';$('#ga-undo').hidden=false;$('#ga-view-archived').hidden=false;await load();}
            else{undoId=null;$('#ga-notice-text').textContent='Đã khôi phục “'+title+'” về bản nháp. Bài chưa được xuất bản.';$('#ga-undo').hidden=true;$('#ga-view-archived').hidden=true;await archiveView('0',true);}
        }catch(error){message('#ga-feedback',error.message);}finally{actionPending=false;$('#ga-undo').disabled=false;}}
    form.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;bodyEditor.sync();busy=true;bodyEditor.disabled(true);$('#ga-fieldset').disabled=true;$('#ga-submit').disabled=true;adminBusy($('#ga-submit'),true);message('#ga-form-error','');const data=new FormData();['title','excerpt','body_html','location_id','author_name','status'].forEach(name=>data.set(name,form.elements[name].value));data.set('is_featured',$('#ga-featured').checked?'1':'0');data.set('remove_cover',$('#ga-remove-cover').checked?'1':'0');const date=$('#ga-published-at').value;data.set('published_at',date===savedPublicationInput?savedPublicationValue:date?new Date(date).toISOString():'');if($('#ga-cover-file').files[0])data.set('cover',$('#ga-cover-file').files[0]);if(currentId)data.set('_method','PUT');try{data.set('category_id',await resolveCategory());await api(currentId?'/'+currentId:'',{method:'POST',body:data});editor.close();adminToast('Đã lưu bài viết. Trạng thái được cập nhật theo lựa chọn của bạn.','success');await meta();await load();}catch(error){message('#ga-form-error',error.message);}finally{busy=false;bodyEditor.disabled(false);$('#ga-fieldset').disabled=false;$('#ga-submit').disabled=false;adminBusy($('#ga-submit'),false);}});
    root.querySelectorAll('[data-ga-close]').forEach(node=>node.addEventListener('click',()=>{if(!busy)editor.close();}));editor.addEventListener('cancel',event=>{if(busy)event.preventDefault();});editor.addEventListener('close',()=>{if(coverUrl)URL.revokeObjectURL(coverUrl);coverUrl='';});$('#ga-cover-file').addEventListener('change',showCover);$('#ga-remove-cover').addEventListener('change',()=>{if($('#ga-remove-cover').checked)$('#ga-cover-file').value='';showCover();});
    $('#ga-preview-button').addEventListener('click',async()=>{bodyEditor.sync();message('#ga-form-error','');$('#ga-preview-button').disabled=true;try{const data=await api('/preview',{method:'POST',body:JSON.stringify({body_html:$('#ga-body').value})});/* Only server-rebuilt allowlisted HTML enters this preview. */$('#ga-preview').innerHTML=data.body_html;$('#ga-preview').hidden=false;}catch(error){message('#ga-form-error',error.message);}finally{$('#ga-preview-button').disabled=false;}});
    $('#ga-status').addEventListener('change',syncStatus);
    $('#ga-active-tab').addEventListener('click',()=>archiveView('0'));$('#ga-archived-tab').addEventListener('click',()=>archiveView('1'));$('#ga-view-archived').addEventListener('click',()=>archiveView('1'));$('#ga-undo').addEventListener('click',()=>{if(undoId!==null)action(undoId,'restore');});
    $('#ga-create').addEventListener('click',()=>open());$('#ga-filters').addEventListener('submit',event=>{event.preventDefault();page=1;load();});$('#ga-retry').addEventListener('click',init);$('#ga-setup-retry').addEventListener('click',init);$('#ga-prev').addEventListener('click',()=>{if(page>1){page--;load();}});$('#ga-next').addEventListener('click',()=>{if(page<lastPage){page++;load();}});
    function resetCategory(){categoryId=null;$('#ga-category-form').reset();$('#ga-category-save').textContent='Thêm';message('#ga-category-error','');}
    function renderCategories(){const list=$('#ga-category-list');list.replaceChildren();categories.forEach(item=>{const row=make('div','ga-category-row'),label=make('div','');label.append(make('strong','',item.name),make('small','',(item.is_active?'Đang hiển thị':'Đang ẩn')+' · '+item.posts_count+' bài viết'));const actions=make('div','ga-actions');actions.append(button('Sửa',()=>{categoryId=item.id;$('#ga-category-name').value=item.name;$('#ga-category-active').checked=item.is_active;$('#ga-category-save').textContent='Lưu';message('#ga-category-error','');$('#ga-category-name').focus();}));const remove=button('Xóa',async()=>{if(!await adminConfirm({title:'Xóa danh mục?',message:'Danh mục “'+item.name+'” sẽ bị xóa. Chỉ có thể xóa danh mục không còn bài viết.',confirmText:'Xóa danh mục'}))return;message('#ga-category-error','');try{await api('/categories/'+item.id,{method:'DELETE'});resetCategory();await meta();await load();}catch(error){message('#ga-category-error',error.message);}},'delete');remove.disabled=item.posts_count>0;if(remove.disabled)remove.title='Danh mục còn bài viết nên chưa thể xóa.';actions.append(remove);row.append(label,actions);list.append(row);});}
    $('#ga-categories').addEventListener('click',()=>{resetCategory();categoryDialog.showModal();});$('#ga-category-close').addEventListener('click',()=>categoryDialog.close());$('#ga-category-reset').addEventListener('click',resetCategory);
    $('#ga-category-form').addEventListener('submit',async event=>{event.preventDefault();$('#ga-category-save').disabled=true;message('#ga-category-error','');try{await api('/categories'+(categoryId?'/'+categoryId:''),{method:categoryId?'PUT':'POST',body:JSON.stringify({name:$('#ga-category-name').value,is_active:$('#ga-category-active').checked})});resetCategory();await meta();await load();}catch(error){message('#ga-category-error',error.message);}finally{$('#ga-category-save').disabled=false;}});
    async function init(){state('loading');$('#ga-create').disabled=true;$('#ga-categories').disabled=true;try{await meta();await load();}catch(error){failed(error);}}init();
})();
</script>
